import os
import time
from collections.abc import Iterator

import requests
from dotenv import load_dotenv

from ...core.exceptions import CouldNotFetchJobs, MissingEnvironmentVariable
from ...database.models import Job

# RATELIMIT
# 60 per minute (1 / s) and 10,000 per day

API_URL = "https://himalayas.app/jobs/api"
PAGE_SIZE = 20
REQUEST_TIMEOUT = 30
REQUEST_DELAY = 2  # seconds


def fetch_himalayas_listings(max_iterations: int | None) -> Iterator[Job]:
    """
    We fetch the himalayas listings using a requests.Session, convert the
    json into a Job object and yield the list every 20 jobs.
    """
    load_dotenv("app.env")

    api_key = os.getenv("HIMALAYAS_API_KEY")

    if not api_key:
        raise MissingEnvironmentVariable("HIMALAYAS_API_KEY variable is not set.")

    cursor: str | None = None

    with requests.Session() as session:
        session.headers.update(
            {
                "Authorization": f"Bearer {api_key}",
            }
        )

        iterations = 0

        while True:
            params = {"limit": PAGE_SIZE}

            if cursor:
                params["cursor"] = cursor

            try:
                response = session.get(
                    API_URL,
                    params=params,
                    timeout=REQUEST_TIMEOUT,
                )
                response.raise_for_status()
                payload = response.json()

            except (requests.RequestException, ValueError) as exc:
                raise CouldNotFetchJobs(
                    f"Failed to fetch Himalayas listings: {exc}",
                    {"error": str(exc)},
                ) from exc

            items = payload.get("jobs")

            if not isinstance(items, list):
                raise CouldNotFetchJobs(
                    "Invalid Himalayas API response: missing or invalid 'jobs'.",
                    payload,
                )

            yield (Job.from_himalayas(item) for item in items)

            next_cursor = payload.get("nextCursor")

            if not next_cursor:
                break

            if next_cursor == cursor:
                raise CouldNotFetchJobs(
                    "Himalayas API returned the same cursor twice.",
                    payload,
                )

            cursor = next_cursor
            iterations += 1

            if max_iterations is not None and iterations >= max_iterations:
                break

            time.sleep(REQUEST_DELAY)
